item.command:
/bin/bash -lc "node --input-type=module <<'EOF'
import assert from 'node:assert/strict'

for (const [path, title, description, heading, links] of [
  ['/', 'Home Page', 'Welcome to our Next.js app', 'Home', ['/about', '/contact']],
  ['/about', 'About Us', 'Learn more about us', 'About', ['/', '/contact']],
]) {
  const response = await fetch("'`http://localhost:3100${path}`)
  const html = await response.text()
  assert.equal(response.status, 200, path)
  assert.match(html, /<html lang="en">/)
  assert.ok(html.includes(`<title>${title}</title>`), `${path} title`)
  assert.ok(html.includes(`name="description" content="${description}"`), `${path} description`)
  assert.ok(html.includes(`<h1>${heading}</h1>`), `${path} heading`)
  for (const href of links) assert.ok(html.includes(`href="${href}"`), `${path} link to ${href}`)
  console.log(`${path}: 200, content, metadata and links verified`)
}
const response = await fetch('"'http://localhost:3100/contact')
assert.equal(response.status, 404)
console.log('/contact: 404, matching the existing missing route')
EOF"

